function missingSpecStatus(product: Product, key: string): string {
  const source = product.specs;
  const automaticDrip = product.category === "커피 머신" && source["추출 방식"]?.includes("자동 드립");
  const manualGrinder = product.category === "그라인더" && source["구동 방식"] === "수동";

  if (product.category === "그라인더") {
    if (manualGrinder && ["모터 출력", "자동 종료", "정전기 저감", "회전수"].includes(key)) return "해당 사항 없음";
    if (manualGrinder && key === "분쇄 속도") return "수동 (사용자 속도)";
    if (manualGrinder && key === "도징 방식") return "싱글도징 / 수동 투입";
    if (manualGrinder && key === "도징 컵") return "기본 구성 확인 필요";
    if (["잔량", "정전기 저감", "회전수"].includes(key)) return "제조사 미공개";
    if (key === "도징 컵") return "구성품 확인 필요";
    if (key === "자동 종료") return "지원 여부 확인 필요";
    if (key === "버 호환") return "호환성 확인 필요";
  }

  if (product.category === "커피 머신") {
    const espressoOnlyKeys = ["보일러 용량", "보일러 출력", "듀얼 보일러", "동시 추출·스팀", "포타필터", "바스켓", "펌프", "권장 추출압", "프리인퓨전", "3-way 솔레노이드 밸브", "백플러싱", "OPV", "스팀 완드", "우유 온도 조절", "우유 거품 조절", "자동 퍼지", "온수 기능", "추출 용량 설정", "압력계", "유량계"];
    if (automaticDrip && espressoOnlyKeys.includes(key)) return "해당 사항 없음";
    if (key === "스팀 기능" && automaticDrip) return "미탑재";
    if (["보일러 용량", "보일러 출력", "예열 시간", "크기", "무게", "소비전력"].includes(key)) return "제조사 사양 확인 필요";
    if (["3-way 솔레노이드 밸브", "백플러싱", "OPV", "자동 퍼지", "압력계", "유량계"].includes(key)) return "탑재 여부 확인 필요";
    if (["스팀 완드", "우유 온도 조절", "우유 거품 조절"].includes(key)) return source["스팀 기능"] === "미탑재" ? "해당 사항 없음" : "세부 사양 확인 필요";
    if (key === "온수 기능") return "지원 여부 확인 필요";
    if (key === "자동 물 분배" || key === "보온판") return automaticDrip ? "제조사 사양 확인 필요" : "해당 사항 없음";
  }

  if (product.category === "드리퍼") {
    if (key === "밸브") return "미탑재";
    if (key === "바이패스 제어") return "별도 제어 기능 없음";
    if (key === "보온 특성") return "단열 기능 미확인";
    if (key === "식기세척기") return "제조사 세척 안내 확인 필요";
    if (["크기", "무게", "제조국"].includes(key)) return "제조사 사양 확인 필요";
  }

  if (product.category === "필터") {
    if (key === "매수") return "판매 구성 확인 필요";
    if (key === "린싱 권장") return "레시피·취향에 따라 다름";
  }

  if (product.category === "첨가액") {
    if (key === "에스프레소 머신 사용") return "제조사 사용 안내 확인 필요";
    if (key === "혼합 사용") return "혼합 가능 여부 확인 필요";
    if (key === "보관·취급") return "제품 라벨의 보관 안내 확인 필요";
    if (key === "국내 참고가") return "국내 판매가 확인 필요";
  }

  if (product.category === "프레스·침출") {
    if (key === "밸브") return "미탑재";
    if (key === "샤워헤드" || key === "탬퍼") return "구성품 확인 필요";
    if (key === "전원") return "전원 필요 여부 확인 필요";
    if (["크기", "무게", "제조국"].includes(key)) return "제조사 사양 확인 필요";
  }

  if (product.category === "서버·포트") {
    if (key === "전자레인지" || key === "식기세척기") return "제조사 사용 안내 확인 필요";
  }

  return "확인 필요";
}

// 알 수 없는 값도 비교표에서 숨기지 않습니다. 사용자가 미공개·해당 없음·확인 필요를 구분할 수 있어야 합니다.
const clean = (value: string) => value.trim() || "확인 필요";

export function getComparableSpecs(product: Product): Record<string, string> {
  const source = product.specs;
  const isManualGrinder = product.category === "그라인더" && source["구동 방식"] === "수동";
  const values: Record<string, string> = {
    ...source,
    "재질": source["재질"] || product.material,
    "출시년도": source["출시년도"] || String(product.year),
    "사용 난이도": source["사용 난이도"] || product.difficulty,
    "분쇄도 조절": source["분쇄도 조절"] || source["분쇄도"] || "",
    "조절 방식": source["조절 방식"] || (isManualGrinder ? source["분쇄도 조절"] || source["분쇄도"] || "" : ""),
    "호퍼 용량": source["호퍼 용량"] || source["도징 용량"] || "",
    "필터 규격": source["필터 규격"] || source["전용 필터"] || "",
    "호환 규격": source["호환 규격"] || source["호환 드리퍼"] || "",
    "형태": source["형태"] || source["추출 방식"] || "",
    "권장 용량": source["권장 용량"] || source["용량"] || "",
    "용량": source["용량"] || source["물 용량"] || "",
    "바이패스 제어": source["바이패스 제어"] || source["바이패스"] || "",
    "샤워헤드": source["샤워헤드"] || source["샤워 스크린"] || "",
    "도징 방식": source["도징 방식"] || (isManualGrinder ? "싱글도징 / 수동 투입" : ""),
    "분쇄 속도": source["분쇄 속도"] || (isManualGrinder ? "수동 (사용자 속도)" : ""),
    "모터 출력": source["모터 출력"] || source["모터"] || (isManualGrinder ? "해당 없음" : ""),
    "자동 종료": source["자동 종료"] || (isManualGrinder ? "해당 없음" : ""),
    "도징 컵": source["도징 컵"] || (isManualGrinder ? "미포함" : ""),
    "잔량": source["잔량"] || (isManualGrinder ? "매우 낮음 (수동 배출)" : ""),
    "정전기 저감": source["정전기 저감"] || (isManualGrinder ? "해당 없음" : ""),
    "회전수": source["회전수"] || (isManualGrinder ? "수동" : ""),
  };
  const ordered = categorySpecOrder[product.category];
  const result: Record<string, string> = {};
  for (const key of ordered) result[key] = clean(values[key] || missingSpecStatus(product, key));
  for (const [key, value] of Object.entries(values)) if (!(key in result)) result[key] = clean(value);
  return result;
}
